UPDATE INST_HEAD SET INSTITUTION_ID = #{institutionId}, STATUS_CD = #{to}, MERGED_INTO_ID = #{mergedInto,jdbcType=NUMERIC},
       MATCHED_BY = #{by}, MATCHED_AT = #{at}
 WHERE HEAD_ID = #{headId} AND INSTITUTION_ID IS NULL AND STATUS_CD = 'CANDIDATE'

