SELECT  FROM INST_HEAD_ITEM
 WHERE HEAD_ID = #{headId} AND FIELD_CD = #{fieldCd} AND STATE_CD = #{stateCd}
 ORDER BY ITEM_ID

SELECT  FROM INST_HEAD_ITEM
 WHERE HEAD_ID = #{headId} AND STATE_CD = #{stateCd}
 ORDER BY ITEM_ID

SELECT COUNT(*) FROM INST_HEAD_ACT
 WHERE ACTOR_EMP_NO = #{actorEmpNo} AND ACTION_CD IN ('VIEW', 'PHOTO_VIEW', 'UNMATCHED_VIEW') AND OUTCOME = 'OK'
   AND LOGGED_AT >= #{since}
